// Git's default conflictMarkerSize is 7. Matches <<<<<<< / ======= / >>>>>>>
// handling elsewhere (editor-client diff.js and this resolver).
var DIFF3_BASE_MARKER = /^\|{7}(?: |$)/;

/**
 * Apply per-conflict A/B resolutions to a working-tree file that still
 * contains git conflict markers.
 *
 * `resolutions` is keyed by 1-based start line of each `<<<<<<<` marker,
 * matching the object built by the editor conflict UI:
 *   {
 *     changeStart,   // line of <<<<<<<
 *     separator,     // line of ======= (not |||||||)
 *     changeEnd,     // line of >>>>>>>
 *     selection      // "A" (ours/local) or "B" (theirs/remote)
 *   }
 *
 * The default `merge` conflict style is:
 *   <<<<<<<
 *   ours
 *   =======
 *   theirs
 *   >>>>>>>
 *
 * `diff3` / `zdiff3` insert a common-ancestor section:
 *   <<<<<<<
 *   ours
 *   ||||||| <base>
 *   ancestor
 *   =======
 *   theirs
 *   >>>>>>>
 *
 * The ancestor section is never part of either chosen side. Selecting "A"
 * must stop at `|||||||`, not at `=======`.
 */
function applyResolutions(content, resolutions) {
    var lines = content.split("\n");
    var result = [];
    var ignoreBlock = false;
    var currentBlock;
    for (var i = 1; i <= lines.length; i++) {
        if (resolutions.hasOwnProperty(i)) {
            currentBlock = resolutions[i];
            if (currentBlock.selection === "A") {
                ignoreBlock = false;
            } else {
                ignoreBlock = true;
            }
            continue;
        }
        if (currentBlock) {
            // Discard the diff3/zdiff3 base section for both A and B.
            // Only treat ||||||| as a marker while we are still before the
            // ======= separator the editor recorded.
            if (i < currentBlock.separator && DIFF3_BASE_MARKER.test(lines[i - 1])) {
                ignoreBlock = true;
                continue;
            }
            if (currentBlock.separator === i) {
                if (currentBlock.selection === "A") {
                    ignoreBlock = true;
                } else {
                    ignoreBlock = false;
                }
                continue;
            } else if (currentBlock.changeEnd === i) {
                currentBlock = null;
                continue;
            } else if (ignoreBlock) {
                continue;
            }
        }
        result.push(lines[i - 1]);
    }
    return result.join("\n");
}

module.exports = {
    applyResolutions: applyResolutions
};
